use std::hint::black_box;
include!("compare.rs");
#[inline(never)]fn bench<const M:u8>(pairs:&[(Item<'_>,Item<'_>)],reps:usize)->u128{let start=std::time::Instant::now();for i in 0..reps{let(x,y)=black_box(&pairs[i&255]);let v=match M{0=>predicates(x,y),1=>two_relations(x,y),2=>ordering_match(x,y),_=>fused(x,y)};black_box(v);}start.elapsed().as_nanos()}
fn main(){let mut scenarios=Vec::new();for len in [0,1,7,8,15,16,27,31,32,33,64,128,1024]{for kind in ["equal","first","last"]{if len==0&&kind!="equal"{continue}scenarios.push((len,kind,0));}}for rate in [43,128]{scenarios.push((27,"mixed",rate));}for kind in ["unequal_len","equal_integer_lt","equal_integer_gt"]{scenarios.push((27,kind,0));}
 let mut seed=1807u64;let mut samples=Vec::new();let mut checked=0;for (len,kind,rate)in scenarios{let a="a".repeat(len);let mut b=a.as_bytes().to_vec();if len>0{if kind=="first"{b[0]=b'b'}else if kind!="equal"&& !kind.starts_with("equal_integer"){b[len-1]=b'b';}}if kind=="unequal_len"{b.push(b'a')}let b=String::from_utf8(b).unwrap();let pairs:Vec<_>=(0..256).map(|i|{let eq=kind=="mixed"&&(i*73%256)<rate;let mut p=((a.as_str(),if kind=="equal_integer_lt"{0}else{usize::MAX}),(if eq{a.as_str()}else{b.as_str()},if kind=="equal_integer_gt"{0}else{usize::MAX}));if i&1==1{p=(p.1,p.0)}p}).collect();for(x,y)in &pairs{let want=predicates(x,y);assert_eq!(want,two_relations(x,y));assert_eq!(want,ordering_match(x,y));assert_eq!(want,fused(x,y));checked+=1;}for rnd in 0..5{let mut modes=[0,1,2,3];for i in(1..4).rev(){seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;modes.swap(i,seed as usize%(i+1));}for mode in modes{let reps=if len>128{200000}else{500000};let ns=match mode{0=>bench::<0>(&pairs,reps),1=>bench::<1>(&pairs,reps),2=>bench::<2>(&pairs,reps),_=>bench::<3>(&pairs,reps)};samples.push(format!("{{\"len\":{len},\"kind\":\"{kind}\",\"equal_slots\":{rate},\"round\":{rnd},\"mode\":{mode},\"reps\":{reps},\"elapsed_ns\":{ns}}}"));}}}println!("{{\"checked_pairs\":{checked},\"samples\":[{}]}}",samples.join(","));}
